ALTER TABLE "products" DROP CONSTRAINT IF EXISTS "products_mvp_product_type_check";
ALTER TABLE "products" ADD CONSTRAINT "products_mvp_product_type_check" CHECK ("product_type" IN ('digital_download','course','community','membership','appointment','event_ticket','bundle'));
ALTER TABLE "orders" ADD COLUMN IF NOT EXISTS "discount_amount" double precision NOT NULL DEFAULT 0;
ALTER TABLE "orders" ADD COLUMN IF NOT EXISTS "promotion_code" text;
ALTER TABLE "orders" ADD COLUMN IF NOT EXISTS "trial_days" integer NOT NULL DEFAULT 0;
CREATE TABLE "marketplace_seller_profiles" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"business_id" uuid NOT NULL REFERENCES "businesses"("id") ON DELETE cascade,"user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE cascade,"display_name" text NOT NULL,"slug" text NOT NULL UNIQUE,"headline" text NOT NULL DEFAULT '',"bio" text NOT NULL DEFAULT '',"support_email" text NOT NULL,"brand_color" text NOT NULL DEFAULT '#1d9bf0',"logo_url" text,"refund_policy" text NOT NULL,"fulfillment_sla_hours" integer NOT NULL DEFAULT 24,"country" text,"tax_responsibility" text NOT NULL DEFAULT 'platform_provider_pending',"operational_policy_version" text NOT NULL,"operational_policy_accepted_at" timestamp NOT NULL,"onboarding_status" text NOT NULL DEFAULT 'active',"risk_status" text NOT NULL DEFAULT 'clear',"status" text NOT NULL DEFAULT 'active',"created_at" timestamp NOT NULL DEFAULT now(),"updated_at" timestamp NOT NULL DEFAULT now(),CONSTRAINT "marketplace_seller_business_unique" UNIQUE("business_id"),CONSTRAINT "marketplace_seller_tax_check" CHECK("tax_responsibility" IN ('seller','platform_provider_pending')));
CREATE TABLE "marketplace_policy_acceptances" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"seller_profile_id" uuid NOT NULL REFERENCES "marketplace_seller_profiles"("id") ON DELETE cascade,"user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE restrict,"policy_type" text NOT NULL,"policy_version" text NOT NULL,"accepted_at" timestamp NOT NULL DEFAULT now(),"evidence" json NOT NULL DEFAULT '{}'::json,CONSTRAINT "marketplace_policy_acceptance_unique" UNIQUE("seller_profile_id","policy_type","policy_version"));
CREATE TABLE "marketplace_promotions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"seller_profile_id" uuid NOT NULL REFERENCES "marketplace_seller_profiles"("id") ON DELETE cascade,"business_id" uuid NOT NULL REFERENCES "businesses"("id") ON DELETE cascade,"name" text NOT NULL,"code" text NOT NULL,"discount_type" text NOT NULL,"percentage_bps" integer NOT NULL DEFAULT 0,"fixed_amount_cents" integer NOT NULL DEFAULT 0,"trial_days" integer NOT NULL DEFAULT 0,"product_ids" json NOT NULL DEFAULT '[]'::json,"minimum_subtotal_cents" integer NOT NULL DEFAULT 0,"starts_at" timestamp,"ends_at" timestamp,"maximum_redemptions" integer NOT NULL DEFAULT 0,"maximum_per_buyer" integer NOT NULL DEFAULT 1,"status" text NOT NULL DEFAULT 'active',"created_at" timestamp NOT NULL DEFAULT now(),"updated_at" timestamp NOT NULL DEFAULT now(),CONSTRAINT "marketplace_promotion_business_code_unique" UNIQUE("business_id","code"));
CREATE TABLE "marketplace_promotion_redemptions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"promotion_id" uuid NOT NULL REFERENCES "marketplace_promotions"("id") ON DELETE restrict,"order_id" uuid NOT NULL UNIQUE REFERENCES "orders"("id") ON DELETE cascade,"buyer_user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE restrict,"discount_amount_cents" integer NOT NULL,"status" text NOT NULL DEFAULT 'reserved',"created_at" timestamp NOT NULL DEFAULT now(),"redeemed_at" timestamp,"reversed_at" timestamp);
CREATE INDEX "marketplace_promotion_redemptions_limit_idx" ON "marketplace_promotion_redemptions"("promotion_id","buyer_user_id","status");
CREATE TABLE "marketplace_bundles" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"seller_profile_id" uuid NOT NULL REFERENCES "marketplace_seller_profiles"("id") ON DELETE cascade,"business_id" uuid NOT NULL REFERENCES "businesses"("id") ON DELETE cascade,"product_id" integer NOT NULL UNIQUE REFERENCES "products"("id") ON DELETE cascade,"slug" text NOT NULL UNIQUE,"status" text NOT NULL DEFAULT 'active',"created_at" timestamp NOT NULL DEFAULT now(),"updated_at" timestamp NOT NULL DEFAULT now());
CREATE TABLE "marketplace_bundle_items" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"bundle_id" uuid NOT NULL REFERENCES "marketplace_bundles"("id") ON DELETE cascade,"product_id" integer NOT NULL REFERENCES "products"("id") ON DELETE restrict,"sort_order" integer NOT NULL DEFAULT 0,"created_at" timestamp NOT NULL DEFAULT now(),CONSTRAINT "marketplace_bundle_item_unique" UNIQUE("bundle_id","product_id"));
CREATE TABLE "marketplace_support_cases" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"case_number" text NOT NULL UNIQUE,"order_id" uuid NOT NULL REFERENCES "orders"("id") ON DELETE restrict,"product_id" integer REFERENCES "products"("id") ON DELETE set null,"buyer_user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE restrict,"seller_user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE restrict,"category" text NOT NULL,"priority" text NOT NULL DEFAULT 'normal',"summary" text NOT NULL,"requested_refund_cents" integer NOT NULL DEFAULT 0,"approved_refund_cents" integer NOT NULL DEFAULT 0,"status" text NOT NULL DEFAULT 'open',"provider_action_status" text NOT NULL DEFAULT 'not_required',"resolution_note" text NOT NULL DEFAULT '',"created_at" timestamp NOT NULL DEFAULT now(),"updated_at" timestamp NOT NULL DEFAULT now(),"resolved_at" timestamp);
CREATE INDEX "marketplace_support_party_status_idx" ON "marketplace_support_cases"("seller_user_id","buyer_user_id","status");
CREATE TABLE "marketplace_support_messages" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,"case_id" uuid NOT NULL REFERENCES "marketplace_support_cases"("id") ON DELETE cascade,"author_user_id" integer NOT NULL REFERENCES "users"("id") ON DELETE restrict,"body" text NOT NULL,"visibility" text NOT NULL DEFAULT 'participants',"created_at" timestamp NOT NULL DEFAULT now());
